#[allow(dead_code)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum A64EncodeError {
    FieldOutOfRange {
        insn: &'static str,
        field: &'static str,
        value: u32,
        width: u8,
    },
}

#[allow(dead_code)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum A64RewriteError {
    UnsupportedField {
        insn: &'static str,
        field: &'static str,
    },
    FieldOutOfRange {
        insn: &'static str,
        field: &'static str,
        value: u32,
        width: u8,
    },
}

fn encode_a64_field(
    insn: &'static str,
    field: &'static str,
    value: u32,
    width: u8,
    shift: u8,
) -> Result<u32, A64EncodeError> {
    if width < 32 && value >= (1_u32 << width) {
        return Err(A64EncodeError::FieldOutOfRange {
            insn,
            field,
            value,
            width,
        });
    }
    Ok(value << shift)
}

fn validate_a64_rewrite_field(
    insn: &'static str,
    field: &'static str,
    value: u32,
    width: u8,
) -> Result<(), A64RewriteError> {
    if width < 32 && value >= (1_u32 << width) {
        return Err(A64RewriteError::FieldOutOfRange {
            insn,
            field,
            value,
            width,
        });
    }
    Ok(())
}

